"""DMGHG Local HTTP Bridge Service.

Provides a clean, local-only HTTP interface to the installed DMGHG Windows native bridge.
Does not start any GUI, does not modify the target installation directory, and does not read user accounts.
"""
import argparse
import ctypes
import json
import os
from pathlib import Path
import sys
import tempfile
import threading
import time
from http.server import HTTPServer, BaseHTTPRequestHandler
from socketserver import ThreadingMixIn
from urllib.parse import parse_qs, urlsplit


def installed_version(exe):
    """Read PE version metadata; the resolver rejects unsupported client versions."""
    version = ctypes.windll.version
    size = version.GetFileVersionInfoSizeW(str(exe), None)
    if not size:
        raise RuntimeError("Cannot read the installed application's version metadata")
    buffer = ctypes.create_string_buffer(size)
    if not version.GetFileVersionInfoW(str(exe), 0, size, buffer):
        raise RuntimeError("Cannot read application version info")
    info = ctypes.c_void_p()
    length = ctypes.c_uint()
    if not version.VerQueryValueW(buffer, "\\", ctypes.byref(info), ctypes.byref(length)):
        raise RuntimeError("Application version structure is missing")
    fields = ctypes.cast(info, ctypes.POINTER(ctypes.c_uint32))
    if fields[0] != 0xFEEF04BD or length.value < 52:
        raise RuntimeError("Application version structure is invalid")
    return f"{fields[2] >> 16}.{fields[2] & 65535}.{fields[3] >> 16}"


class Bridge:
    READ_COMMANDS = {
        "app.ping", "catalog.get_channels", "catalog.get_banners",
        "catalog.get_video_list", "catalog.search_video", "catalog.get_video_key",
        "catalog.get_video_detail", "catalog.get_channel_detail", "video.play",
    }

    def __init__(self, app_dir):
        if os.name != "nt":
            raise RuntimeError("The installed bridge requires Windows x64 Python")
        self.app_dir = Path(app_dir).resolve(strict=True)
        self.dll_path = self.app_dir / "electron_bridge.dll"
        if not self.dll_path.is_file():
            raise RuntimeError("electron_bridge.dll is missing from the selected application")
        self.state_root = Path(tempfile.mkdtemp(prefix="dmghg-headless-"))
        os.environ["DMGHG_TEST_DATA_ROOT"] = str(self.state_root)
        os.environ["RUST_LOG"] = "error"
        self.dll = ctypes.CDLL(str(self.dll_path))
        self.dll.dmghg_service_new.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
        self.dll.dmghg_service_new.restype = ctypes.c_void_p
        self.dll.dmghg_service_handle_command_json.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.dll.dmghg_service_handle_command_json.restype = ctypes.c_void_p
        self.dll.dmghg_string_free.argtypes = [ctypes.c_void_p]
        self.dll.dmghg_service_free.argtypes = [ctypes.c_void_p]
        self.lock = threading.RLock()
        self.version = installed_version(self.app_dir / "dmghg.exe")
        self.handle = self.dll.dmghg_service_new(b"dmghg-flutter", self.version.encode("ascii"))
        if not self.handle:
            raise RuntimeError("The installed bridge could not initialize")

    def call(self, command, payload=None):
        if command not in self.READ_COMMANDS:
            raise PermissionError(f"Command '{command}' is outside the inspection allowlist")
        payload = payload or {}
        # Ensure type conventions required by the native bridge
        if command == "catalog.search_video":
            if "page" in payload:
                payload["page"] = str(payload["page"])
        elif command == "catalog.get_video_list":
            if "page" in payload:
                try:
                    payload["page"] = int(payload["page"])
                except Exception:
                    pass
            if "channel" in payload:
                try:
                    payload["channel"] = int(payload["channel"])
                except Exception:
                    pass
        elif command == "catalog.get_video_detail":
            if "id" in payload:
                payload["id"] = str(payload["id"])
        elif command == "video.play":
            if "id" in payload:
                payload["id"] = str(payload["id"])
            if "resolve" not in payload:
                payload["resolve"] = True

        request = {
            "request_id": f"bridge-{int(time.time()*1000)}",
            "protocol_version": 1,
            "command": command,
            "payload": payload
        }
        with self.lock:
            previous = Path.cwd()
            try:
                # The installed Lua resolver loads resources/lua relative to Cwd.
                os.chdir(self.app_dir)
                ptr = self.dll.dmghg_service_handle_command_json(
                    self.handle, json.dumps(request, ensure_ascii=False).encode("utf-8"))
                if not ptr:
                    raise RuntimeError("Bridge returned a null response")
                try:
                    response = json.loads(ctypes.string_at(ptr).decode("utf-8"))
                finally:
                    self.dll.dmghg_string_free(ptr)
            finally:
                os.chdir(previous)

        if response.get("ok") is not True:
            error = response.get("error", {})
            raise RuntimeError(f"{error.get('code')}: {error.get('message')}")
        return response.get("data")

    def close(self):
        with self.lock:
            if self.handle:
                self.dll.dmghg_service_free(self.handle)
                self.handle = None


class ThreadingHTTPServer(ThreadingMixIn, HTTPServer):
    daemon_threads = True
    allow_reuse_address = True


class BridgeRequestHandler(BaseHTTPRequestHandler):
    timeout = 8.0
    protocol_version = "HTTP/1.1"

    def send_json(self, status_code, data):
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(body)

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Connection", "close")
        self.end_headers()

    def do_GET(self):
        parsed = urlsplit(self.path)
        path = parsed.path.rstrip("/") or "/"
        bridge = self.server.bridge

        if path == "/ping":
            self.send_json(200, {"ok": True, "data": "pong", "version": bridge.version})
            return

        if path == "/channels":
            try:
                data = bridge.call("catalog.get_channels")
                self.send_json(200, {"ok": True, "data": data})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"message": str(e)}})
            return

        # Convenience query routes
        params = parse_qs(parsed.query)
        if path == "/api/list":
            try:
                ch = params.get("channel", ["20"])[0]
                pg = params.get("page", ["1"])[0]
                data = bridge.call("catalog.get_video_list", {"channel": ch, "page": pg})
                self.send_json(200, {"ok": True, "data": data})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"message": str(e)}})
            return

        if path == "/api/search":
            try:
                k = params.get("key", [""])[0]
                pg = params.get("page", ["1"])[0]
                data = bridge.call("catalog.search_video", {"key": k, "page": pg})
                self.send_json(200, {"ok": True, "data": data})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"message": str(e)}})
            return

        if path == "/api/detail":
            try:
                vid = params.get("id", [""])[0]
                data = bridge.call("catalog.get_video_detail", {"id": vid})
                self.send_json(200, {"ok": True, "data": data})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"message": str(e)}})
            return

        if path == "/api/play":
            try:
                vid = params.get("id", [""])[0]
                part = params.get("part", [""])[0]
                play_tag = params.get("play", [""])[0]
                data = bridge.call("video.play", {"id": vid, "part": part, "play": play_tag, "resolve": True})
                self.send_json(200, {"ok": True, "data": data})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"message": str(e)}})
            return

        self.send_json(404, {"ok": False, "error": {"code": "not_found", "message": f"Route '{path}' not found"}})

    def do_POST(self):
        parsed = urlsplit(self.path)
        path = parsed.path.rstrip("/") or "/"
        bridge = self.server.bridge

        content_length_str = self.headers.get("Content-Length")
        if not content_length_str:
            self.send_json(411, {"ok": False, "error": {"message": "Length Required"}})
            return

        try:
            content_length = int(content_length_str)
        except ValueError:
            self.send_json(400, {"ok": False, "error": {"message": "Invalid Content-Length"}})
            return

        # Bound request payload to 1MB
        if content_length > 1024 * 1024:
            self.send_json(413, {"ok": False, "error": {"message": "Payload Too Large"}})
            return

        try:
            raw_body = self.rfile.read(content_length)
            body = json.loads(raw_body.decode("utf-8")) if raw_body else {}
        except Exception as e:
            self.send_json(400, {"ok": False, "error": {"message": f"Malformed JSON: {e}"}})
            return

        if path == "/call":
            command = body.get("command")
            payload = body.get("payload", {})
            if not command:
                self.send_json(400, {"ok": False, "error": {"message": "Missing 'command' parameter"}})
                return

            try:
                result = bridge.call(command, payload)
                self.send_json(200, {"ok": True, "data": result})
            except PermissionError as pe:
                self.send_json(403, {"ok": False, "error": {"code": "forbidden", "message": str(pe)}})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"message": str(e)}})
            return

        self.send_json(404, {"ok": False, "error": {"code": "not_found", "message": f"Route '{path}' not found"}})

    def log_message(self, format, *args):
        # Silent headless logging; no terminal spam
        pass


def run_server(app_dir, port=18002):
    bridge = Bridge(app_dir)
    server_address = ("127.0.0.1", port)
    httpd = ThreadingHTTPServer(server_address, BridgeRequestHandler)
    httpd.bridge = bridge
    print(f"DMGHG Bridge running on [REDACTED_URL] (app: {app_dir}, version: {bridge.version})")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
        bridge.close()
        print("DMGHG Bridge closed gracefully.")


def main():
    parser = argparse.ArgumentParser(description="DMGHG Local HTTP Bridge Service")
    parser.add_argument("--app-dir", default=r"D:\太极\动漫共和国概念版", help="Path to installed application directory")
    parser.add_argument("--port", type=int, default=18002, help="Loopback port to bind (default: 18002)")
    args = parser.parse_args()
    run_server(args.app_dir, args.port)


if __name__ == "__main__":
    main()

